bearer.description:
Authentication works by passing the VBO API Key as a bearer token.<br>
Additionaly, the the request needs to be validated using a HMACSHA256 hash of its content.

Example request:

    string apiUrl = "https://eventmanager.vbotickets.com/api2/eventdate/{id}";
    string requestBody = "";

    // generate hash consisting of the full unencoded api URL (including query strings) + the postdata
    // hashed using HMACSHA256 with the users secret key
    HMACSHA256Generator sha256 = new HMACSHA256Generator();
    string newHash = sha256.Hash(apiUrl + requestBody, "6C69616F68626C1729H7377867763518E4534376F6766616E");

    HttpRequestMessage msg = new HttpRequestMessage
    {
        Method = HttpMethod.Get,
        RequestUri = new Uri(apiUrl)
    };
    msg.Headers.Add("Version", "1.0"); // Version of the currently used API. Required.
    msg.Headers.Add("Authorization", "Bearer DH7289HU-C78H-4393-KH9U-EA75287D00FF"); // Authorization key. Required.
    msg.Headers.Add("SecretHash", newHash); // Request hash

    using (HttpClient client = new HttpClient())
    {
        content = await client.SendAsync(msg);
    }

    //parse json result
    string result = await content.Content.ReadAsStringAsync();

## Hashing
The following hash function is recommended

    public string Hash(string input, string secret)
    {
        Byte[] textBytes = Encoding.UTF8.GetBytes(input);

        // The key is hex encoded, so it has´to be decoded prior to hashing
        Byte[] keyBytes = HexDecode(secret);
        Byte[] hashBytes;

        using (HMACSHA256 hash = new HMACSHA256(keyBytes))
            hashBytes = hash.ComputeHash(textBytes);

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    private static byte[] HexDecode(string hex)
    {
        var bytes = new byte[hex.Length / 2];
        for (int i = 0; i < bytes.Length; i++)
        {
            bytes[i] = byte.Parse(hex.Substring(i * 2, 2), NumberStyles.HexNumber);
        }
        return bytes;
    }
